import{_ as a,o as t,c as s,a3 as i}from"./chunks/framework.C_NFtyrq.js";const u=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/getting-started.md","filePath":"tutorials/getting-started.md"}'),o={name:"tutorials/getting-started.md"};function r(h,e,n,d,l,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Push-triggered CI on a repo, end to end, in ~10 minutes.</p><p>bupha ships as tamias packages — the fleet is a <code>type: bupha</code> bundle and the <code>bupha</code> command is a <code>bins[]</code> shim pack (<code>libraries/bupha</code>, ADR-0006 amendment + T-012). You install the bundle with tamias, the provider unit runs the watcher engine through <code>tamias-driver-bupha host</code>, and GitHub pushes flow webhook → queue → worktree → pipeline → commit status.</p><p>Prereqs: <strong>Linux + systemd</strong> (provider units need systemd; the shell runner needs bash; macOS/Windows unsupported for now); git; the <code>tamias</code> CLI; the <code>bupha</code> command pack — <code>tamias install 9aia:bupha@&lt;version&gt;</code> from the org registry (needs <code>TAMIAS_REGISTRY_TOKEN</code>), or <code>scripts/pack.sh</code> + <code>tamias install --allow-drivers ./libraries/bupha</code> from a checkout — which registers <code>tamias-driver-bupha</code> into <code>$TAMIAS_HOME/drivers/</code> (<code>cargo build --release -p bupha-driver</code> from this repo produces the binary by hand); a stable public URL for the webhook — named cloudflared tunnel or a direct box; quick tunnels are convenient but flaky. Docker only if you use the dagger runner.</p><p>The shipped bundles live in <code>libraries/</code> — <code>ci-gate</code> (push gate on <code>main</code>) and <code>docs-deploy</code> (push to <code>docs</code> → site deploy). This tutorial walks <code>ci-gate</code>; swap the name for your own bundle.</p><h2 id="_1-secrets-first-—-names-only-in-config-values-in-cuora" tabindex="-1">1. Secrets first — names only in config, values in cuora <a class="header-anchor" href="#_1-secrets-first-—-names-only-in-config-values-in-cuora" aria-label="Permalink to &quot;1. Secrets first — names only in config, values in cuora&quot;">​</a></h2><p>Canonical store is cuora (T-056):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%s&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BUPHA_TOKEN_VALUE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">   |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> cuora</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> put</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cuora://bupha/BUPHA_TOKEN</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%s&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WEBHOOK_SECRET_VALUE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> cuora</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> put</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cuora://bupha/BUPHA_WEBHOOK_SECRET</span></span></code></pre></div><p>(<code>BUPHA_TOKEN</code> is a repo-scoped PAT for statuses + hook management; <code>BUPHA_WEBHOOK_SECRET</code> is the HMAC secret GitHub signs deliveries with. Fallback when cuora isn&#39;t available: <code>~/.config/bupha/env</code> — the dev-mode / no-cuora leg (the OS-keyring leg was dropped post-T-077).)</p><h2 id="_2-install-the-bundle" tabindex="-1">2. Install the bundle <a class="header-anchor" href="#_2-install-the-bundle" aria-label="Permalink to &quot;2. Install the bundle&quot;">​</a></h2><p><code>tamias install &lt;ref&gt;</code> — fetch + unpack the bundle payload (driver <code>install</code> is a no-op; the payload&#39;s <code>fleet.toml</code> + <code>tamias.yaml</code> are the config sources).</p><h2 id="_3-deploy-it" tabindex="-1">3. Deploy it <a class="header-anchor" href="#_3-deploy-it" aria-label="Permalink to &quot;3. Deploy it&quot;">​</a></h2><p><code>tamias deploy ci-gate</code> — renders <code>bupha-watch.service</code> <strong>and</strong><code>bupha-worker.service</code> (one ingress mode each — enable ONE, see <a href="/bupha/how-to/tamias-bundles.html">tamias bundles</a>) <strong>and</strong> runs the driver&#39;s <code>deploy</code> verb: merges <code>fleet.toml</code> with the manifest&#39;s <code>provider.ingress</code> and writes <code>~/.config/bupha/bundles/ci-gate.toml</code> — the file both units&#39; <code>tamias-driver-bupha host|worker --config …</code> consume.</p><h2 id="_4-register-the-webhook" tabindex="-1">4. Register the webhook <a class="header-anchor" href="#_4-register-the-webhook" aria-label="Permalink to &quot;4. Register the webhook&quot;">​</a></h2><p><code>tamias driver exec ci-gate hooks register --dry-run</code> — print the webhook plan, then <code>… hooks register</code> for real (needs the secrets above). This wires GitHub → the bundle&#39;s public URL — <strong>standalone/dev ingress</strong> (ADR-0007); production ingress is a peregrin campaign listener.</p><h2 id="_5-start-the-watcher" tabindex="-1">5. Start the watcher <a class="header-anchor" href="#_5-start-the-watcher" aria-label="Permalink to &quot;5. Start the watcher&quot;">​</a></h2><p><code>tamias service enable bupha-watch</code> — start the standalone watcher (<code>loginctl enable-linger</code> once for boot persistence); <code>bupha-worker</code> is the substrate/production alternative — see <a href="/bupha/how-to/distributed-runners.html">distributed runners</a>.</p><h2 id="_6-check-health" tabindex="-1">6. Check health <a class="header-anchor" href="#_6-check-health" aria-label="Permalink to &quot;6. Check health&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> driver</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci-gate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> health</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # ping /hook + unit probe (JSON)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> driver</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci-gate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # per-unit is-active/is-enabled</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> driver</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci-gate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # journalctl over the provider units</span></span></code></pre></div><h2 id="_7-push" tabindex="-1">7. Push <a class="header-anchor" href="#_7-push" aria-label="Permalink to &quot;7. Push&quot;">​</a></h2><p><code>ci/bupha</code> commit status appears; superseded/cancelled shas get honest error statuses.</p><p>Done. Logs: <code>journalctl --user -u bupha-watch -f</code> (or <code>tamias driver exec ci-gate logs --lines 200</code>).</p><h2 id="what-you-now-know" tabindex="-1">What you now know <a class="header-anchor" href="#what-you-now-know" aria-label="Permalink to &quot;What you now know&quot;">​</a></h2><ul><li>bupha is tamias-distributed: bundles are <code>type: bupha</code> content packs; the product surface is <code>tamias install</code>/<code>deploy</code> plus <code>tamias driver exec &lt;bundle&gt; health|status|logs|hooks</code>, with the watcher engine running inside the provider unit via <code>tamias-driver-bupha host</code>.</li><li>Secrets are names in config, values in cuora (<code>cuora://</code> refs) with <code>~/.config/bupha/env</code> as the dev-mode fallback.</li><li>One bundle deploys two units (<code>bupha-watch</code>, <code>bupha-worker</code>) — you enable the ingress mode you want; GitHub webhooks flow HMAC-verified into a dedup&#39;d queue → detached worktree → pipeline → commit status.</li></ul><h2 id="local-reproduction-dev-harness" tabindex="-1">Local reproduction (dev harness) <a class="header-anchor" href="#local-reproduction-dev-harness" aria-label="Permalink to &quot;Local reproduction (dev harness)&quot;">​</a></h2><p>To reproduce a red run without touching the deployment, use the dev CLI — install the command pack (<code>scripts/pack.sh</code> then <code>tamias install --allow-drivers ./libraries/bupha</code> from this repo), then in the repo: <code>bupha doctor</code> checks the box against a config, <code>bupha run</code> executes the configured runner in the watched <code>dir</code> — the same pipeline, locally. <code>bupha watch</code> runs the whole engine standalone (no tamias, no peregrin) — the ADR-0007 fallback ingress, not the product path.</p><h2 id="where-next" tabindex="-1">Where next <a class="header-anchor" href="#where-next" aria-label="Permalink to &quot;Where next&quot;">​</a></h2><ul><li><strong>How-to</strong> (tasks): <a href="/bupha/how-to/tamias-bundles.html">tamias bundles</a> · <a href="/bupha/how-to/multi-repo.html">multi-repo</a> · <a href="/bupha/how-to/shell-runner.html">shell runner</a> · <a href="/bupha/how-to/gha-runner.html">gha runner — your own GHA workflows</a> · <a href="/bupha/how-to/self-hosted-runner.html">self-hosted GHA runner</a> · <a href="/bupha/how-to/distributed-runners.html">distributed runners</a> · <a href="/bupha/how-to/sccache-backend.html">sccache backend</a></li><li><strong>Reference</strong> (lookup): <a href="/bupha/reference/cli.html">cli — dev harness</a> · <a href="/bupha/reference/config.html">config</a> · <a href="/bupha/reference/crate-api.html">crate api</a></li><li><strong>Explanation</strong> (why): <a href="/bupha/explanation/architecture.html">architecture</a> · <a href="/bupha/explanation/release-model.html">release model</a> · <a href="/bupha/comparison.html">comparison</a> — vs GHA/hosted CI · <a href="/bupha/explanation/crate-scope-audit.html">crate scope audit</a></li></ul><p>Project: <a href="https://github.com/9aia/bupha/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING</a> · <a href="https://github.com/9aia/bupha/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY</a> · <a href="https://github.com/9aia/bupha/blob/main/project/index.md" target="_blank" rel="noreferrer">project</a> — TODO, backlog, ADRs</p>`,29)])])}const k=a(o,[["render",r]]);export{u as __pageData,k as default};
